// One reusable model runtime per page. Camera ownership stays with DlcEngine.
export class DlcRuntime {
 constructor({createWorker=()=>new Worker('/dlc-worker.js'),later=(fn,ms)=>setTimeout(fn,ms),cancel=id=>clearTimeout(id)}={}){this.createWorker=createWorker;this.later=later;this.cancel=cancel;this.worker=null;this.listener=null;this.lease=0;this.ready=null;this.retry=0;this.retryTimer=null;this.idleTimer=null;this.loadTimer=null;}
 preload(){if(!this.worker&&!this.retryTimer)this.launch();this.armIdle();}
 acquire(listener){if(this.listener)throw Error('The DLC camera already owns the detector.');if(this.idleTimer)this.cancel(this.idleTimer);this.idleTimer=null;const lease=++this.lease;this.listener=listener;if(!this.worker&&!this.retryTimer)this.launch();const snapshot=this.ready;if(snapshot)queueMicrotask(()=>{if(this.lease===lease&&this.listener===listener)listener(snapshot);});return {send:frame=>{if(this.listener===listener&&this.lease===lease)this.worker?.postMessage({...frame,session:lease},frame.pixels?[frame.pixels]:[]);},release:()=>{if(this.listener!==listener||this.lease!==lease)return;this.listener=null;this.worker?.postMessage({type:'idle'});this.armIdle();},recover:reason=>{if(this.listener===listener&&this.lease===lease)this.recover(reason);}};}
 launch(){try{const worker=this.createWorker();this.worker=worker;this.loadTimer=this.later(()=>{if(this.worker===worker&&!this.ready)this.recover('Material model is taking longer than expected. Retrying while the camera stays open.');},90000);worker.onmessage=({data})=>{if(this.worker!==worker)return;if(data.type==='fatal'){this.recover(data.error||'Detector recovery in progress.');return;}if(data.type==='ready'){this.ready=data;this.retry=0;if(this.loadTimer)this.cancel(this.loadTimer);this.loadTimer=null;}if(data.type==='coverage'&&this.ready)this.ready={...this.ready,...data,type:'ready'};if((data.type==='result'||data.type==='skipped')&&data.session!==this.lease)return;this.listener?.(data);};worker.onerror=()=>{if(this.worker===worker)this.recover('Restarting the detector. Camera stays open.');};}catch(error){this.recover(error.message||'The detector could not start.');}}
 recover(reason){if(this.retryTimer)return;if(this.loadTimer)this.cancel(this.loadTimer);this.loadTimer=null;this.worker?.terminate();this.worker=null;this.ready=null;this.listener?.({type:'restarting',reason});const delay=Math.min(30000,1000*2**Math.min(this.retry++,5));this.retryTimer=this.later(()=>{this.retryTimer=null;if(this.listener)this.launch();},delay);}
 armIdle(){if(this.listener||this.idleTimer)return;this.idleTimer=this.later(()=>this.dispose(),300000);}
 dispose(){for(const timer of [this.idleTimer,this.retryTimer,this.loadTimer])if(timer)this.cancel(timer);this.worker?.postMessage({type:'dispose'});this.worker?.terminate();this.worker=null;this.ready=null;this.listener=null;this.idleTimer=this.retryTimer=this.loadTimer=null;this.lease++;}
}
export const dlcRuntime=new DlcRuntime();
